6	//
7	//===----------------------------------------------------------------------===//
8	//
9	// Tests for orc-rt's TaskGroup.h APIs.
10	//
11	//===----------------------------------------------------------------------===//
12	
13	#include "orc-rt/TaskGroup.h"
14	#include "gtest/gtest.h"
15	
16	#include <atomic>
17	#include <chrono>
18	#include <thread>
19	#include <vector>
20	
21	using namespace orc_rt;
22	
23	TEST(TaskGroupTest, TrivialConstructionAndDestruction) {
24	  auto TG = TaskGroup::Create();
25	}
26	
27	TEST(TaskGroupTest, SingleTokenThenClose) {
28	  bool Completed = false;
29	  auto TG = TaskGroup::Create();
30	  TG->addOnComplete([&]() { Completed = true; });
31	
32	  {
33	    TaskGroup::Token T(TG);
34	    EXPECT_TRUE(T);
35	    TG->close();
36	    EXPECT_FALSE(Completed);
37	  }
38	  EXPECT_TRUE(Completed);
39	}
40	
41	TEST(TaskGroupTest, CloseWithNoTokens) {
42	  bool Completed = false;
43	  auto TG = TaskGroup::Create();
44	  TG->addOnComplete([&]() { Completed = true; });
45	  TG->close();
46	  EXPECT_TRUE(Completed);
47	}
48	
49	TEST(TaskGroupTest, TokenFromClosedGroup) {
50	  auto TG = TaskGroup::Create();
51	  TG->close();
52	  TaskGroup::Token T(TG);
53	  EXPECT_FALSE(T);
54	}
55	
56	TEST(TaskGroupTest, TokenFromNullSharedPtr) {
57	  std::shared_ptr<TaskGroup> TG;
58	  TaskGroup::Token T(TG);
59	  EXPECT_FALSE(T);
60	}
61	
62	TEST(TaskGroupTest, CopyToken) {
63	  bool Completed = false;
64	  auto TG = TaskGroup::Create();
65	  TG->addOnComplete([&]() { Completed = true; });
66	
67	  {
68	    TaskGroup::Token T1(TG);
69	    EXPECT_TRUE(T1);
70	    {
71	      TaskGroup::Token T2(T1); // Copy increments count
72	      EXPECT_TRUE(T2);
73	      TG->close();
74	      EXPECT_FALSE(Completed);
75	    }
76	    EXPECT_FALSE(Completed); // T1 still alive
77	  }
78	  EXPECT_TRUE(Completed);
79	}
80	
81	TEST(TaskGroupTest, MoveToken) {
82	  bool Completed = false;
83	  auto TG = TaskGroup::Create();
84	  TG->addOnComplete([&]() { Completed = true; });
85	
86	  TaskGroup::Token T1(TG);
87	  TaskGroup::Token T2(std::move(T1));
88	  EXPECT_FALSE(T1);
89	  EXPECT_TRUE(T2);
90	
91	  TG->close();
92	  EXPECT_FALSE(Completed);
93	
94	  T2 = TaskGroup::Token(); // Release
95	  EXPECT_TRUE(Completed);
96	}
97	
98	TEST(TaskGroupTest, CopyAssignmentReleasesOld) {
99	  bool Completed1 = false;
100	  bool Completed2 = false;
101	  auto TG1 = TaskGroup::Create();
102	  auto TG2 = TaskGroup::Create();
103	  TG1->addOnComplete([&]() { Completed1 = true; });
104	  TG2->addOnComplete([&]() { Completed2 = true; });
105	
106	  TaskGroup::Token T1(TG1);
107	  TaskGroup::Token T2(TG2);
108	
109	  TG1->close();
110	  TG2->close();
111	
112	  EXPECT_FALSE(Completed1);
113	  EXPECT_FALSE(Completed2);
114	
115	  T1 = T2; // Releases TG1, acquires TG2
116	
117	  EXPECT_TRUE(Completed1);  // TG1 should complete
118	  EXPECT_FALSE(Completed2); // TG2 still has T1 and T2
119	}
120	
121	TEST(TaskGroupTest, CopyAssignmentFromClosedGroup) {
122	  bool Completed = false;
123	  auto TG1 = TaskGroup::Create();
124	  auto TG2 = TaskGroup::Create();
125	  TG1->addOnComplete([&]() { Completed = true; });
126	  TG2->close();
127	
128	  TaskGroup::Token T1(TG1);
129	  TaskGroup::Token T2(TG2);
130	  EXPECT_TRUE(T1);
131	  EXPECT_FALSE(T2);
132	
133	  TG1->close();
134	  EXPECT_FALSE(Completed);
135	
136	  T1 = T2; // Assign from empty, releases TG1
137	  EXPECT_FALSE(T1);
138	  EXPECT_TRUE(Completed);
139	}
140	
141	TEST(TaskGroupTest, MoveAssignmentReleasesOld) {
142	  bool Completed1 = false;
143	  bool Completed2 = false;
144	  auto TG1 = TaskGroup::Create();
145	  auto TG2 = TaskGroup::Create();
146	  TG1->addOnComplete([&]() { Completed1 = true; });
147	  TG2->addOnComplete([&]() { Completed2 = true; });
148	
149	  TaskGroup::Token T1(TG1);
150	  TaskGroup::Token T2(TG2);
151	
152	  TG1->close();
153	  TG2->close();
154	
155	  EXPECT_FALSE(Completed1);
156	  EXPECT_FALSE(Completed2);
157	
158	  T1 = std::move(T2); // Releases TG1, takes TG2 from T2
159	
160	  EXPECT_TRUE(Completed1);  // TG1 should complete
161	  EXPECT_FALSE(Completed2); // TG2 now held by T1
162	  EXPECT_FALSE(T2);         // T2 is now empty
163	}
164	
165	TEST(TaskGroupTest, SelfCopyAssignment) {
166	  auto TG = TaskGroup::Create();
167	  TaskGroup::Token T(TG);
168	  EXPECT_TRUE(T);
169	
170	#if defined(__clang__)
171	#pragma clang diagnostic push
172	#pragma clang diagnostic ignored "-Wself-assign-overloaded"
173	#endif
174	  T = T; // Self-assign
175	#if defined(__clang__)
176	#pragma clang diagnostic pop
177	#endif
178	
179	  EXPECT_TRUE(T); // Should still be valid
180	
181	  TG->close();
182	}
183	
184	TEST(TaskGroupTest, SelfMoveAssignment) {
185	  auto TG = TaskGroup::Create();
186	  TaskGroup::Token T(TG);
187	  EXPECT_TRUE(T);
188	
189	#if defined(__clang__)
190	#pragma clang diagnostic push
191	#pragma clang diagnostic ignored "-Wself-move"
192	#endif
193	  T = std::move(T); // Self-move-assign
194	#if defined(__clang__)
195	#pragma clang diagnostic pop
196	#endif
197	
198	  EXPECT_TRUE(T); // Should still be valid
199	
200	  TG->close();
201	}
202	
203	TEST(TaskGroupTest, AddOnCompleteAfterCompletion) {
204	  auto TG = TaskGroup::Create();
205	  TG->close();
206	
207	  bool Completed = false;
208	  TG->addOnComplete([&]() { Completed = true; });
209	  EXPECT_TRUE(Completed); // Runs immediately
210	}
211	
212	TEST(TaskGroupTest, AddOnCompleteWhileTasksPending) {
213	  auto TG = TaskGroup::Create();
214	  TaskGroup::Token T(TG);
215	  TG->close();
216	
217	  bool Completed = false;
218	  TG->addOnComplete([&]() { Completed = true; });
219	  EXPECT_FALSE(Completed); // Queued, not run yet
220	
221	  T = TaskGroup::Token(); // Release
222	  EXPECT_TRUE(Completed);
223	}
224	
225	TEST(TaskGroupTest, MultipleCallbacks) {
226	  std::vector<int> Order;
227	  auto TG = TaskGroup::Create();
228	  TG->addOnComplete([&]() { Order.push_back(1); });
229	  TG->addOnComplete([&]() { Order.push_back(2); });
230	  TG->addOnComplete([&]() { Order.push_back(3); });
231	  TG->close();
232	
233	  ASSERT_EQ(Order.size(), 3u);
234	  EXPECT_EQ(Order[0], 1);
235	  EXPECT_EQ(Order[1], 2);
236	  EXPECT_EQ(Order[2], 3);
237	}
238	
239	TEST(TaskGroupTest, MultipleTokens) {
240	  int CompletionCount = 0;
241	  auto TG = TaskGroup::Create();
242	  TG->addOnComplete([&]() { CompletionCount++; });
243	
244	  {
245	    TaskGroup::Token T1(TG);
246	    TaskGroup::Token T2(TG);
247	    TaskGroup::Token T3(TG);
248	    TG->close();
249	    EXPECT_EQ(CompletionCount, 0);
250	  }
251	  EXPECT_EQ(CompletionCount, 1); // Only fires once
252	}
253	
254	TEST(TaskGroupTest, CloseIsIdempotent) {
255	  int CompletionCount = 0;
256	  auto TG = TaskGroup::Create();
257	  TG->addOnComplete([&]() { CompletionCount++; });
258	
259	  TG->close();
260	  TG->close();
261	  TG->close();
262	
263	  EXPECT_EQ(CompletionCount, 1);
264	}
265	
266	TEST(TaskGroupTest, AcquireAfterCloseViaDirectAPI) {
267	  auto TG = TaskGroup::Create();
268	  EXPECT_TRUE(TG->acquireToken());
269	  TG->close();
270	  EXPECT_FALSE(TG->acquireToken());
271	  TG->releaseToken(); // Release the one we acquired
272	}
273	
274	TEST(TaskGroupTest, DirectAPIMatchesRAII) {
275	  bool Completed = false;
276	  auto TG = TaskGroup::Create();
277	  TG->addOnComplete([&]() { Completed = true; });
278	
279	  TG->acquireToken();
280	  TG->acquireToken();
281	  TG->close();
282	
283	  EXPECT_FALSE(Completed);
284	  TG->releaseToken();
285	  EXPECT_FALSE(Completed);
286	  TG->releaseToken();
287	  EXPECT_TRUE(Completed);
288	}
289	
290	TEST(TaskGroupTest, TokenKeepsTaskGroupAlive) {
291	  TaskGroup::Token T;
292	  bool Completed = false;
293	
