18	class Session::NotificationService : public Service {
19	public:
20	  void addOnDetach(Session::OnDetachFn OnDetach) {
21	    ToNotifyOnDetach.push_back(std::move(OnDetach));
22	  }
23	
24	  void addOnShutdown(Session::OnShutdownFn OnShutdown) {
25	    ToNotifyOnShutdown.push_back(std::move(OnShutdown));
26	  }
