51	Session::ControllerAccess::~ControllerAccess() = default;
52	
53	Session::Session(ExecutorProcessInfo EPI, DispatchFn Dispatch,
54	                 ErrorReporterFn ReportError)
55	    : EPI(std::move(EPI)), Dispatch(std::move(Dispatch)),
56	      ReportError(std::move(ReportError)),
57	      Notifiers(createService<NotificationService>()) {}
58	
59	Session::~Session() {
60	  shutdown();
61	  std::unique_lock<std::mutex> Lock(M);
62	  CV.wait(Lock, [&]() {
63	    return CurrentState == State::Shutdown && TargetState == State::None;
64	  });
65	}
66	
67	void Session::doAttach(std::shared_ptr<ControllerAccess> CA, BootstrapInfo BI) {
68	  assert(CA && "doAttach called with null CA object");
69	
70	  {
71	    std::scoped_lock<std::mutex> Lock(M);
72	    // Controller can only be attached from the start state if no
73	    // other operation has been requested.
74	    if (CurrentState != State::Start || TargetState != State::None)
75	      return;
76	    assert(std::atomic_load(&this->CA) == nullptr &&
77	           "ControllerAccess object already attached?");
78	    std::atomic_store(&this->CA, CA);
79	    TargetState = State::Attached;
80	  }
81	
82	  CA->connect(std::move(BI));
83	
84	  {
85	    std::scoped_lock<std::mutex> Lock(M);
86	    assert(TargetState >= State::Attached || CurrentState >= State::Detached);
87	
88	    // There are three possibilities that we have to deal with here:
89	    // 1. Connection succeeded and we're done.
90	    //
91	    //    We just need to move to the Attached state, reset TargetState, and
92	    //    we're done.
93	    //
94	    // 2. Connect failed.
95	    //
96	    //    In this case connect must have called notifyDisconnected, which
97	    //    should have initiated the detach. We just need to bail out.
98	    //
99	    // 3. Connection succeeded but a detach or shutdown was requested
100	    //    concurrently. In this case we need to start the detach process.
101	    //
102	    // To distinguish between these we first look at the target state. If it's
103	    // Attached then it's option (1) and we're done:
104	    if (TargetState == State::Attached) {
105	      CurrentState = State::Attached;
106	      TargetState = State::None;
107	      return;
108	    }
109	
110	    // The target state is Detached or higher. Check the current state. If it's
111	    // also Detached or higher then notifyDisconnected must already have been
112	    // called (in turn calling proceedToDetach, which updated the current
113	    // state). In this case we're in option (2) and we just need to bail out.
114	    if (CurrentState >= State::Detached)
115	      return;
116	
117	    // The target state is Detached or higher, but the current state is still
118	    // Start. Someone must have called detach / shutdown concurrently. This is
119	    // option (3) and we just need to update the current state and run
120	    // disconnect.
121	    CurrentState = State::Attached;
122	  }
123	
124	  // Fall through to disconnect from case (3) above.
125	  CA->disconnect();
126	}
127	
128	void Session::detach(OnDetachFn OnDetach) {
129	  addOnDetach(std::move(OnDetach));
130	
131	  std::shared_ptr<ControllerAccess> TmpCA;
132	  {
133	    std::unique_lock<std::mutex> Lock(M);
134	
135	    // Check if someone's already managing transitions.
136	    if (TargetState != State::None) {
137	      TargetState = std::max(TargetState, State::Detached);
138	      return;
139	    }
140	
141	    // Nobody's managing transitions, but this request is redundant.
142	    if (CurrentState >= State::Detached)
143	      return;
144	
145	    // We've actually got work to do.
146	    TargetState = State::Detached;
147	    assert((CurrentState == State::Start || CurrentState == State::Attached) &&
148	           "Unexpected current state");
149	
150	    if (CurrentState == State::Attached) {
151	      assert(CA && "Attached, but not CA?");
152	      TmpCA = std::atomic_load(&this->CA);
153	    } else {
154	      assert(CurrentState == State::Start);
155	      proceedToDetach(Lock, std::atomic_exchange(&this->CA, {}));
156	      return;
157	    }
158	  }
159	
160	  TmpCA->disconnect();
161	}
162	
163	void Session::shutdown(OnShutdownFn OnShutdown) {
164	  addOnShutdown(std::move(OnShutdown));
165	
166	  std::shared_ptr<ControllerAccess> TmpCA;
167	  {
168	    std::unique_lock<std::mutex> Lock(M);
169	
170	    // Check if someone's already managing transitions.
171	    if (TargetState != State::None) {
172	      TargetState = std::max(TargetState, State::Shutdown);
173	      return;
174	    }
175	
176	    // Nobody's managing transition, but this request is redundant.
177	    if (CurrentState == State::Shutdown)
178	      return;
179	
180	    TargetState = State::Shutdown;
181	    assert((CurrentState == State::Start || CurrentState == State::Attached ||
182	            CurrentState == State::Detached) &&
183	           "Unexpected current state");
184	
185	    switch (CurrentState) {
186	    case State::Start:
187	      proceedToDetach(Lock, nullptr);
188	      return;
189	    case State::Attached:
190	      TmpCA = std::atomic_load(&this->CA);
191	      break;
192	    case State::Detached:
193	      Lock.unlock();
194	      waitForManagedCodeTasksThenShutdown();
195	      return;
196	    default:
197	      assert(false && "Illegal state");
198	      abort();
199	    }
200	  }
201	
202	  TmpCA->disconnect();
203	}
204	
205	void Session::addOnDetach(OnDetachFn OnDetach) {
206	  if (!OnDetach)
207	    return;
208	  {
209	    std::scoped_lock<std::mutex> Lock(M);
210	    if (CurrentState < State::Detached) {
211	      Notifiers.addOnDetach(std::move(OnDetach));
212	      return;
213	    }
214	  }
215	  // We've already detached. Run in-place.
216	  OnDetach();
217	}
218	
219	void Session::addOnShutdown(OnShutdownFn OnShutdown) {
220	  if (!OnShutdown)
221	    return;
222	  {
223	    std::scoped_lock<std::mutex> Lock(M);
224	    if (CurrentState < State::Shutdown) {
225	      Notifiers.addOnShutdown(std::move(OnShutdown));
226	      return;
227	    }
228	  }
229	  // We've already shutdown. Run in-place.
230	  OnShutdown();
231	}
232	
233	void Session::appendService(std::unique_ptr<Service> Srv) {
234	
235	  bool ShuttingDown = false;
236	  {
237	    std::scoped_lock<std::mutex> Lock(M);
238	    if (CurrentState < State::Detached) {
239	      Services.push_back(std::move(Srv));
240	      return;
241	    }
242	    ShuttingDown = TargetState == State::Shutdown;
243	  }
244	
245	  // Already detached. Call onDetach on the service.
246	  assert(Srv && "Should be non-null here");
247	  Srv->onDetach([]() {}, ShuttingDown);
248	
249	  // Try to append again.
250	  {
251	    std::scoped_lock<std::mutex> Lock(M);
252	    if (CurrentState < State::Shutdown) {
253	      Services.push_back(std::move(Srv));
254	      return;
255	    }
256	  }
257	
258	  // Already shutdown. Call onShutdown on the service.
259	  assert(Srv && "Should be non-null here");
260	  Srv->onShutdown([]() {});
261	
262	  // At this point the service has already been shut down, but we need to keep
263	  // the object alive until the Session is destroyed, so append it anyway.
264	  {
265	    std::scoped_lock<std::mutex> Lock(M);
266	    Services.push_back(std::move(Srv));
267	  }
268	}
269	
270	void Session::handleDisconnect() {
271	  // If we get here we _don't_ need to call disconnect.
272	  std::unique_lock<std::mutex> Lock(M);
273	  assert(CurrentState <= State::Attached);
274	  TargetState = std::max(TargetState, State::Detached);
